# ============================================
# RESUMEN DE PRUEBAS
# ============================================
Write-Host ""
Write-Host "╔══════════════════════════════════════════╗" -ForegroundColor Cyan
Write-Host "║           RESUMEN DE PRUEBAS            ║" -ForegroundColor Cyan
Write-Host "╚══════════════════════════════════════════╝" -ForegroundColor Cyan
Write-Host ""
Write-Host "  Total de pruebas: $totalTests" -ForegroundColor White
