$testRegister = Read-Host "¿Deseas probar el registro de un nuevo aprendiz? (S/N)"

if ($testRegister -eq "S" -or $testRegister -eq "s") {
    Write-Host "Ingresa los datos del aprendiz:" -ForegroundColor Cyan
