using Xunit;
using FluentAssertions;
using Moq;
using System.Net;
using System.Net.Http;
using System.Threading.Tasks;
using System.Text.Json;
using AutogestionSena.MAUI.Api.Services;
using AutogestionSena.MAUI.Api.Dtos;

namespace AutogestionSenaMaui.Tests.Services
{
    /// <summary>
    /// Pruebas unitarias para ApiService
    /// </summary>
    public class ApiServiceTests
    {
        private readonly ApiService _apiService;

        public ApiServiceTests()
        {
            _apiService = new ApiService();
        }

        [Fact(DisplayName = "ApiService - Constructor debe crear instancia válida")]
        public void Constructor_ShouldCreateValidInstance()
        {
            // Arrange & Act
            var service = new ApiService();

            // Assert
            service.Should().NotBeNull();
        }

        [Fact(DisplayName = "SetAuthToken - Debe configurar header de autorización")]
        public void SetAuthToken_ShouldConfigureAuthorizationHeader()
        {
            // Arrange
            var token = "test_token_123";

            // Act
            _apiService.SetAuthToken(token);

            // Assert - El token debe estar configurado (verificación indirecta)
            // No podemos verificar directamente el header privado, pero podemos
            // verificar que no lanza excepción
            _apiService.Invoking(s => s.SetAuthToken(token))
                .Should().NotThrow();
        }

        [Fact(DisplayName = "ClearAuthToken - Debe limpiar header de autorización")]
        public void ClearAuthToken_ShouldClearAuthorizationHeader()
        {
            // Arrange
            _apiService.SetAuthToken("test_token");

            // Act
            _apiService.ClearAuthToken();

            // Assert - Verificar que no lanza excepción
            _apiService.Invoking(s => s.ClearAuthToken())
                .Should().NotThrow();
        }

        [Theory(DisplayName = "SetAuthToken - Debe manejar tokens nulos o vacíos")]
        [InlineData(null)]
        [InlineData("")]
        [InlineData("   ")]
        public void SetAuthToken_ShouldHandleInvalidTokens(string? invalidToken)
        {
            // Act & Assert
            _apiService.Invoking(s => s.SetAuthToken(invalidToken!))
                .Should().NotThrow();
        }
    }
}
